const baseNode = $('Prompt Base (Fixo)').first().json;
const modNode = $('Prompt do Módulo (Entrada Modular)').first().json;

const basePrompt = String(baseNode.prompt_base || '').trim();
if (!basePrompt) {
  throw new Error('Prompt Base vazio. Preencha o campo "prompt_base" no nó "Prompt Base (Fixo)".');
}

const modulePrompt = String(modNode.prompt_modulo || modNode.prompt_modulo_padrao || '').trim();
if (!modulePrompt) {
  throw new Error('Especificação do módulo vazia. Preencha o formulário, envie "module_prompt" no Webhook ou configure "prompt_modulo_padrao".');
}

const projectSlug = String(modNode.project_slug || 'sistema_busca_freelances')
  .trim()
  .toLowerCase()
  .replace(/[^a-z0-9_-]/g, '_');

const moduleName = String(modNode.module_name || 'modulo_01')
  .trim()
  .toLowerCase()
  .replace(/[^a-z0-9_-]/g, '_');

const previousState = String(modNode.previous_state || '').trim();

const projectId = (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function')
  ? crypto.randomUUID()
  : `proj-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;

const rawBudget = Number(modNode.budget_limit_usd);
const budgetLimitUsd = (!Number.isNaN(rawBudget) && rawBudget > 0) ? rawBudget : 5.0;

const rawPrompt = `${basePrompt}\n\n========================================\nMÓDULO ATUAL (${moduleName})\n========================================\n${modulePrompt}${previousState ? `\n\n========================================\nESTADO DE MÓDULOS ANTERIORES\n========================================\n${previousState}` : ''}`;

return [{
  json: {
    project_id: projectId,
    project_slug: projectSlug,
    module_name: moduleName,
    base_prompt: basePrompt,
    module_prompt: modulePrompt,
    previous_state: previousState,
    raw_prompt: rawPrompt,
    budget_limit_usd: budgetLimitUsd,
    spent_usd: 0,
    retry_count: 0,
    max_retries: 3,
    usage_log: []
  }
}];

const ctx = $('Init Project & Budget').first().json;
const resp = $input.first().json;
const requirements = JSON.parse(resp.choices[0].message.content);

const pTokens = resp.usage?.prompt_tokens || 0;
const cTokens = resp.usage?.completion_tokens || 0;
const cost = Number((((pTokens / 1000000) * 2.0) + ((cTokens / 1000000) * 8.0)).toFixed(6));

return [{
  json: {
    ...ctx,
    spent_usd: Number((ctx.spent_usd + cost).toFixed(6)),
    requirements,
    usage_log: [
      ...ctx.usage_log,
      { agent: 'requirements_analyst', model: 'gpt-4.1', prompt_tokens: pTokens, completion_tokens: cTokens, cost_usd: cost }
    ]
  }
}];

const ctx = $('Track Requirements & Usage').first().json;
const resp = $input.first().json;
const architecture = JSON.parse(resp.choices[0].message.content);

const pTokens = resp.usage?.prompt_tokens || 0;
const cTokens = resp.usage?.completion_tokens || 0;
const cost = Number((((pTokens / 1000000) * 2.0) + ((cTokens / 1000000) * 8.0)).toFixed(6));

const tasks = (architecture.tasks || []).sort((a, b) => (a.phase || 1) - (b.phase || 1));
if (tasks.length === 0) {
  throw new Error('O Software Architect não retornou nenhuma tarefa executável.');
}

const updatedSpent = Number((ctx.spent_usd + cost).toFixed(6));
const updatedUsage = [
  ...ctx.usage_log,
  { agent: 'software_architect', model: 'gpt-4.1', prompt_tokens: pTokens, completion_tokens: cTokens, cost_usd: cost }
];

return tasks.map((task, idx) => ({
  json: {
    project_id: ctx.project_id,
    project_slug: ctx.project_slug,
    module_name: ctx.module_name,
    base_prompt: ctx.base_prompt,
    module_prompt: ctx.module_prompt,
    previous_state: ctx.previous_state,
    raw_prompt: ctx.raw_prompt,
    budget_limit_usd: ctx.budget_limit_usd,
    spent_usd: updatedSpent,
    retry_count: ctx.retry_count,
    max_retries: ctx.max_retries,
    requirements: ctx.requirements,
    architecture,
    usage_log: updatedUsage,
    task_index: idx,
    total_tasks: tasks.length,
    task
  }
}));

const item = $input.first().json;
const task = item.task;

const personas = {
  data_scientist: 'Você é um Data Scientist Sênior especialista em Python, Pandas, Polars, NumPy, SciPy, EDA estatística, limpeza de dados e visualizações reproduzíveis.',
  data_engineer: 'Você é um Data Engineer Sênior especialista em ETL/ELT idempotente, SQLite, SQLAlchemy, validação de schemas com Pydantic e processamento incremental.',
  ml_engineer: 'Você é um Machine Learning Engineer Sênior especialista em Scikit-learn, classificação de compatibilidade, NLP e pontuação de oportunidades.',
  automation_engineer: 'Você é um Automation Engineer Sênior especialista em Python, n8n, webhooks, agendamentos, processamento de e-mails, logs estruturados e manipulação segura de arquivos.',
  scraping_engineer: 'Você é um Web Scraping Engineer Sênior especialista em Playwright, Selenium, BeautifulSoup e Requests. Siga rigorosamente as REGRAS DE ACESSO do Prompt Base (zero bypass de CAPTCHA/autenticação, pausa para intervenção manual e suporte a importação manual).',
  backend_frontend_engineer: 'Você é um Full-Stack Engineer Sênior especialista em Python, Streamlit, FastAPI, arquitetura modular e documentação técnica.'
};

const moduleType = item.requirements?.module_type || 'IMPLEMENTATION';

const systemPrompt = `${item.base_prompt}

=== PAPEL ATUAL: SPECIALIST DEVELOPER (${task.agent_id}) ===
${personas[task.agent_id] || personas.backend_frontend_engineer}

REGRAS OBRIGATÓRIAS:
1. Respeite estritamente o escopo do MÓDULO ATUAL (tipo: ${moduleType}). Se o módulo proibir o desenvolvimento de funcionalidades ainda, produza APENAS os entregáveis de arquitetura, diagramas, esquemas e documentação solicitados.
2. Para tarefas de código: escreva código limpo, modular, com type hints completos, docstrings, logging estruturado, tratamento de exceções e testes unitários em pytest com mocks para chamadas externas.
3. Nunca insira senhas, tokens ou chaves hardcoded (use variáveis de ambiente).
4. Não recrie nem sobrescreva arquivos já aprovados em módulos anteriores sem necessidade.
5. Retorne EXCLUSIVAMENTE um JSON válido: { "task_id": "${task.task_id}", "summary": "resumo técnico", "files": [ { "path": "caminho/relativo", "content": "conteúdo completo" } ] }.`;

const userPrompt = `Projeto: ${item.project_slug} (ID: ${item.project_id})
Módulo Atual: ${item.module_name}
Tarefa: ${task.task_id} (${task.agent_id})
Objetivo: ${task.objective || task.description}
Descrição Técnica: ${task.description}
Tecnologias: ${JSON.stringify(task.technologies || [])}
Input Schema: ${JSON.stringify(task.input_schema || {})}
Output Schema: ${JSON.stringify(task.output_schema || {})}
Arquivos esperados: ${JSON.stringify(task.target_files || task.deliverables || [])}
Critérios de aceitação: ${JSON.stringify(task.acceptance_criteria || [])}

Especificação Completa do Módulo:
${item.module_prompt}${item.previous_state ? `

Estado de Módulos Anteriores:
${item.previous_state}` : ''}

Arquitetura e Contratos:
${JSON.stringify({
  stack: item.architecture.stack,
  directory_structure: item.architecture.directory_structure,
  database_schema: item.architecture.database_schema,
  api_contracts: item.architecture.api_contracts
})}`;

return [{
  json: {
    ...item,
    system_prompt: systemPrompt,
    user_prompt: userPrompt
  }
}];

const ctx = $('Specialist Prompt Router').first().json;
const resp = $input.first().json;
const parsed = JSON.parse(resp.choices[0].message.content);

const pTokens = resp.usage?.prompt_tokens || 0;
const cTokens = resp.usage?.completion_tokens || 0;
const cost = Number((((pTokens / 1000000) * 0.27) + ((cTokens / 1000000) * 1.10)).toFixed(6));

return [{
  json: {
    project_id: ctx.project_id,
    task_id: ctx.task.task_id,
    agent_id: ctx.task.agent_id,
    summary: parsed.summary || 'Módulo implementado',
    files: parsed.files || [],
    usage: {
      agent: ctx.task.agent_id,
      task_id: ctx.task.task_id,
      model: 'deepseek-chat',
      prompt_tokens: pTokens,
      completion_tokens: cTokens,
      cost_usd: cost
    }
  }
}];

const item = $input.first().json;
let taskOutputs = [];
try {
  taskOutputs = $('Collect Task Code & Tokens').all();
} catch (e) {}

const filesMap = {};
for (const out of taskOutputs) {
  for (const f of (out.json.files || [])) {
    if (f.path && typeof f.content === 'string') {
      const cleanPath = f.path.replace(/^(\.\.(\/|\\|$))+/, '').replace(/^\/+/, '');
      filesMap[cleanPath] = f.content;
    }
  }
}

filesMap['BUDGET_EXCEEDED_REPORT.json'] = JSON.stringify({
  project_id: item.project_id,
  project_slug: item.project_slug,
  module_name: item.module_name,
  status: 'BUDGET_EXCEEDED',
  spent_usd: item.spent_usd,
  budget_limit_usd: item.budget_limit_usd,
  message: 'Execução interrompida pelo guardrail financeiro. Os entregáveis concluídos até este ponto foram incluídos neste arquivo ZIP.'
}, null, 2);

const projectSlug = (item.project_slug || item.requirements?.project_name || 'projeto_parcial').replace(/[^a-zA-Z0-9_-]/g, '_');
const moduleSlug = (item.module_name || 'modulo').replace(/[^a-zA-Z0-9_-]/g, '_');
const zipFilename = `${projectSlug}_${moduleSlug}_${item.project_id.slice(0, 8)}_parcial.zip`;
const filePaths = Object.keys(filesMap);

return filePaths.map((relPath) => ({
  json: {
    project_id: item.project_id,
    zip_filename: zipFilename,
    file_path: relPath
  },
  binary: {
    data: {
      data: Buffer.from(filesMap[relPath], 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: relPath
    }
  }
}));

const dagItems = $('Build Execution DAG').all();
const base = dagItems[0].json;
const taskOutputs = $('Collect Task Code & Tokens').all();

const filesMap = {};
const usageLog = [...base.usage_log];
let totalSpent = Number(base.spent_usd);

for (const out of taskOutputs) {
  const d = out.json;
  for (const f of (d.files || [])) {
    if (f.path && typeof f.content === 'string') {
      const cleanPath = f.path.replace(/^(\.\.(\/|\\|$))+/, '').replace(/^\/+/, '');
      filesMap[cleanPath] = f.content;
    }
  }
  if (d.usage) {
    usageLog.push(d.usage);
    totalSpent = Number((totalSpent + Number(d.usage.cost_usd || 0)).toFixed(6));
  }
}

const generatedFiles = Object.entries(filesMap).map(([path, content]) => ({ path, content }));

return [{
  json: {
    project_id: base.project_id,
    project_slug: base.project_slug,
    module_name: base.module_name,
    base_prompt: base.base_prompt,
    module_prompt: base.module_prompt,
    previous_state: base.previous_state,
    raw_prompt: base.raw_prompt,
    budget_limit_usd: base.budget_limit_usd,
    spent_usd: totalSpent,
    retry_count: 0,
    max_retries: base.max_retries,
    requirements: base.requirements,
    architecture: base.architecture,
    usage_log: usageLog,
    files_map: filesMap,
    generated_files: generatedFiles
  }
}];

const prev = $('Consolidate Modules').first().json;
const asmResp = $input.first().json;
const asm = JSON.parse(asmResp.choices[0].message.content);

const pTokens = asmResp.usage?.prompt_tokens || 0;
const cTokens = asmResp.usage?.completion_tokens || 0;
const cost = Number((((pTokens / 1000000) * 0.27) + ((cTokens / 1000000) * 1.10)).toFixed(6));

const filesMap = { ...prev.files_map };
for (const f of (asm.patched_modules || [])) {
  if (f.path && typeof f.content === 'string') {
    const cleanPath = f.path.replace(/^(\.\.(\/|\\|$))+/, '').replace(/^\/+/, '');
    filesMap[cleanPath] = f.content;
  }
}
for (const f of (asm.config_files || [])) {
  if (f.path && typeof f.content === 'string') {
    const cleanPath = f.path.replace(/^(\.\.(\/|\\|$))+/, '').replace(/^\/+/, '');
    filesMap[cleanPath] = f.content;
  }
}

const codeBundle = Object.entries(filesMap).map(([path, content]) => ({ path, content }));

return [{
  json: {
    project_id: prev.project_id,
    project_slug: prev.project_slug,
    module_name: prev.module_name,
    base_prompt: prev.base_prompt,
    module_prompt: prev.module_prompt,
    previous_state: prev.previous_state,
    raw_prompt: prev.raw_prompt,
    budget_limit_usd: prev.budget_limit_usd,
    spent_usd: Number((prev.spent_usd + cost).toFixed(6)),
    retry_count: 0,
    max_retries: prev.max_retries,
    requirements: prev.requirements,
    architecture: prev.architecture,
    usage_log: [
      ...prev.usage_log,
      { agent: 'project_assembler', model: 'deepseek-chat', prompt_tokens: pTokens, completion_tokens: cTokens, cost_usd: cost }
    ],
    files_map: filesMap,
    code_bundle: codeBundle
  }
}];

