let state;
try {
  state = $('Apply Code Patches').last().json;
} catch (e) {
  state = $('Prepare Audit Bundle').first().json;
}

const merged = $input.all();
const qaResp = merged[0]?.json || {};
const secResp = merged[1]?.json || {};

const qaReport = qaResp.choices ? JSON.parse(qaResp.choices[0].message.content) : { approved: false, blocking_issues: [{ severity: 'HIGH', description: 'Falha na leitura do QA Reviewer' }] };
const secReport = secResp.choices ? JSON.parse(secResp.choices[0].message.content) : { secure: false, vulnerabilities: [{ severity: 'HIGH', remediation: 'Falha na leitura do Security Auditor' }] };

const qaTokens = (qaResp.usage?.prompt_tokens || 0) + (qaResp.usage?.completion_tokens || 0);
const secTokens = (secResp.usage?.prompt_tokens || 0) + (secResp.usage?.completion_tokens || 0);
const auditCost = Number((((qaTokens + secTokens) / 1000000) * 4.0).toFixed(6));

const blockingQa = (qaReport.blocking_issues || []).filter(i => ['CRITICAL', 'HIGH'].includes(i.severity));
const blockingSec = (secReport.vulnerabilities || []).filter(v => ['CRITICAL', 'HIGH'].includes(v.severity));
const passed = blockingQa.length === 0 && blockingSec.length === 0;

return [{
  json: {
    ...state,
    spent_usd: Number((state.spent_usd + auditCost).toFixed(6)),
    passed,
    qa_report: qaReport,
    security_report: secReport
  }
}];

